--
-- Name: academic_submissions; Type: TABLE; Schema: public; Owner: collabu_admin
--

CREATE TABLE public.academic_submissions (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    application_id character varying NOT NULL,
    submission_type public.academic_submissions_submission_type_enum DEFAULT 'anteproyecto'::public.academic_submissions_submission_type_enum NOT NULL,
    status public.academic_submissions_status_enum DEFAULT 'pending_submission'::public.academic_submissions_status_enum NOT NULL,
    current_file_id uuid,
    version_number integer DEFAULT 0 NOT NULL,
    correction_count integer DEFAULT 0 NOT NULL,
    jurado_votes jsonb,
    reviewer_comments text,
    asesor_comments text,
    student_response text,
    deadline_for_review timestamp with time zone,
    deadline_for_student timestamp with time zone,
    reviewed_at timestamp with time zone,
    submitted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.academic_submissions OWNER TO collabu_admin;

