--
-- Name: match_feedback; Type: TABLE; Schema: public; Owner: collabu_admin
--

CREATE TABLE public.match_feedback (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    match_result_id uuid NOT NULL,
    user_id character varying NOT NULL,
    feedback_type public.match_feedback_feedback_type_enum NOT NULL,
    comment text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.match_feedback OWNER TO collabu_admin;

--
-- Name: match_recommendations; Type: TABLE; Schema: public; Owner: collabu_admin
--

CREATE TABLE public.match_recommendations (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    match_result_id uuid NOT NULL,
    target_user_id character varying NOT NULL,
    target_type public.match_recommendations_target_type_enum NOT NULL,
    recommendation_type public.match_recommendations_recommendation_type_enum NOT NULL,
    message text,
    is_seen boolean DEFAULT false NOT NULL,
    seen_at timestamp with time zone,
    is_dismissed boolean DEFAULT false NOT NULL,
    dismissed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.match_recommendations OWNER TO collabu_admin;

--
-- Name: match_results; Type: TABLE; Schema: public; Owner: collabu_admin
--

CREATE TABLE public.match_results (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    student_id character varying NOT NULL,
    project_id character varying NOT NULL,
    overall_score numeric(5,2) NOT NULL,
    skills_score numeric(5,2),
    proficiency_score numeric(5,2),
    program_score numeric(5,2),
    semester_score numeric(5,2),
    availability_score numeric(5,2),
    language_score numeric(5,2),
    weights_snapshot jsonb NOT NULL,
    skills_breakdown jsonb,
    compatibility_level public.match_results_compatibility_level_enum,
    is_recommended boolean DEFAULT false NOT NULL,
    calculated_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.match_results OWNER TO collabu_admin;

--
-- Name: match_weights; Type: TABLE; Schema: public; Owner: collabu_admin
--

CREATE TABLE public.match_weights (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    factor_name public.match_weights_factor_name_enum NOT NULL,
    weight numeric(4,3) NOT NULL,
    description text,
    is_active boolean DEFAULT true NOT NULL,
    scope public.match_weights_scope_enum DEFAULT 'global'::public.match_weights_scope_enum NOT NULL,
    scope_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.match_weights OWNER TO collabu_admin;

