CREATE TABLE public.project_activities (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    project_id uuid NOT NULL,
    student_id character varying,
    assigned_by character varying,
    title character varying NOT NULL,
    description text NOT NULL,
    activity_type character varying NOT NULL,
    scheduled_date timestamp with time zone,
    due_date timestamp with time zone,
    completed_date timestamp with time zone,
    status public.project_activities_status_enum DEFAULT 'pending'::public.project_activities_status_enum NOT NULL,
    priority public.project_activities_priority_enum DEFAULT 'medium'::public.project_activities_priority_enum NOT NULL,
    hours_estimated numeric(5,1),
    hours_actual numeric(5,1),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.project_activities OWNER TO collabu_admin;

