-- Name: student_profiles; Type: TABLE; Schema: public; Owner: collabu_admin
--

CREATE TABLE public.student_profiles (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id uuid NOT NULL,
    program character varying(150) NOT NULL,
    program_id uuid,
    faculty character varying(150) DEFAULT 'Facultad de Ingeniería'::character varying NOT NULL,
    semester integer NOT NULL,
    student_code character varying(50),
    enrollment_year integer,
    expected_graduation_year integer,
    gpa numeric(3,2),
    total_credits_completed integer DEFAULT 0 NOT NULL,
    total_credits_required integer,
    bio text,
    headline character varying(255),
    cv_url character varying(500),
    portfolio_url character varying(500),
    github_url character varying(500),
    personal_website_url character varying(500),
    availability public.student_profiles_availability_enum DEFAULT 'flexible'::public.student_profiles_availability_enum NOT NULL,
    preferred_work_mode character varying(50),
    available_hours_per_week integer,
    willing_to_relocate boolean DEFAULT false NOT NULL,
    has_completed_internship boolean DEFAULT false NOT NULL,
    internship_count integer DEFAULT 0 NOT NULL,
    average_rating numeric(3,2) DEFAULT '0'::numeric NOT NULL,
    total_ratings integer DEFAULT 0 NOT NULL,
    profile_completeness integer DEFAULT 0 NOT NULL,
    is_visible boolean DEFAULT true NOT NULL,
    last_cv_generated_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.student_profiles OWNER TO collabu_admin;

